import{_ as i,o,c as n,a0 as t}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Phase 5A: Benchmark Expansion","description":"","frontmatter":{},"headers":[],"relativePath":"internals/hackathon-archive/phase-5a-benchmark-expansion.md","filePath":"internals/hackathon-archive/phase-5a-benchmark-expansion.md"}'),a={name:"internals/hackathon-archive/phase-5a-benchmark-expansion.md"};function r(s,e,l,c,d,g){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="phase-5a-benchmark-expansion" tabindex="-1">Phase 5A: Benchmark Expansion <a class="header-anchor" href="#phase-5a-benchmark-expansion" aria-label="Permalink to &quot;Phase 5A: Benchmark Expansion&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To expand the DevFix autonomous recovery evaluation benchmark from 5 cases to 10 distinct, non-overlapping cases, ensuring a robust test of the agent&#39;s diagnostic logic.</p><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>Five new cases were engineered with precise deterministic verifier integration. Each case required the agent to investigate a broken <code>node_modules</code> structure, missing configuration, syntax errors, or failing build pipelines inside an isolated Docker sandbox.</p><h2 id="case-details" tabindex="-1">Case Details <a class="header-anchor" href="#case-details" aria-label="Permalink to &quot;Case Details&quot;">​</a></h2><h3 id="dev-06-—-dependency-package-configuration-failure" tabindex="-1">DEV-06 — Dependency / Package Configuration Failure <a class="header-anchor" href="#dev-06-—-dependency-package-configuration-failure" aria-label="Permalink to &quot;DEV-06 — Dependency / Package Configuration Failure&quot;">​</a></h3><ul><li><strong>Category</strong>: Dependency Issue</li><li><strong>Difficulty</strong>: Easy</li><li><strong>Setup</strong>: <code>package.json</code> contains <code>express</code> but lacks <code>cors</code>. <code>index.js</code> imports <code>cors</code>.</li><li><strong>Expected Repair</strong>: <code>npm install cors</code></li><li><strong>Verifier</strong>: Process (exit code 0).</li><li><strong>Result</strong>: <strong>SUCCESS</strong> (13 iterations)</li><li><strong>Differentiation</strong>: Tests if the agent can manually correlate an imported but missing package against <code>package.json</code> dependencies.</li></ul><h3 id="dev-07-—-environment-runtime-configuration-failure" tabindex="-1">DEV-07 — Environment / Runtime Configuration Failure <a class="header-anchor" href="#dev-07-—-environment-runtime-configuration-failure" aria-label="Permalink to &quot;DEV-07 — Environment / Runtime Configuration Failure&quot;">​</a></h3><ul><li><strong>Category</strong>: Missing Configuration</li><li><strong>Difficulty</strong>: Medium</li><li><strong>Setup</strong>: Project expects an <code>API_KEY</code> in <code>.env</code>. Only <code>.env.test</code> is provided.</li><li><strong>Expected Repair</strong>: Create <code>.env</code> containing <code>API_KEY</code>.</li><li><strong>Verifier</strong>: Process (exit code 0).</li><li><strong>Result</strong>: <strong>SUCCESS</strong> (7 iterations)</li><li><strong>Differentiation</strong>: Tests environmental context awareness rather than just package installation.</li></ul><h3 id="dev-08-—-file-module-integration-failure" tabindex="-1">DEV-08 — File / Module Integration Failure <a class="header-anchor" href="#dev-08-—-file-module-integration-failure" aria-label="Permalink to &quot;DEV-08 — File / Module Integration Failure&quot;">​</a></h3><ul><li><strong>Category</strong>: Code/Module Path Mismatch</li><li><strong>Difficulty</strong>: Medium</li><li><strong>Setup</strong>: A named export in <code>math.js</code> uses <code>Add</code>, but the importer expects <code>add</code>.</li><li><strong>Expected Repair</strong>: Patch <code>math.js</code> or <code>index.js</code> to align the export/import structure.</li><li><strong>Verifier</strong>: Process (exit code 0).</li><li><strong>Result</strong>: <strong>SUCCESS</strong> (4 iterations)</li><li><strong>Differentiation</strong>: Requires reading across multiple files and patching code logic rather than shell-level fixes.</li></ul><h3 id="dev-09-—-build-configuration-failure" tabindex="-1">DEV-09 — Build / Configuration Failure <a class="header-anchor" href="#dev-09-—-build-configuration-failure" aria-label="Permalink to &quot;DEV-09 — Build / Configuration Failure&quot;">​</a></h3><ul><li><strong>Category</strong>: Build Configuration</li><li><strong>Difficulty</strong>: Hard</li><li><strong>Setup</strong>: <code>webpack.config.js</code> incorrectly points to <code>src/app.js</code> instead of the actual <code>src/index.js</code>.</li><li><strong>Expected Repair</strong>: Patch <code>webpack.config.js</code> entrypoint.</li><li><strong>Verifier</strong>: Process (<code>npm run build</code> exits 0).</li><li><strong>Result</strong>: <strong>SUCCESS</strong> (4 iterations)</li><li><strong>Differentiation</strong>: Tests interaction with toolchain configurations (Webpack) instead of runtime node configurations.</li></ul><h3 id="dev-10-—-multi-step-cascading-failure" tabindex="-1">DEV-10 — Multi-Step Cascading Failure <a class="header-anchor" href="#dev-10-—-multi-step-cascading-failure" aria-label="Permalink to &quot;DEV-10 — Multi-Step Cascading Failure&quot;">​</a></h3><ul><li><strong>Category</strong>: Cascading Diagnostic Flow</li><li><strong>Difficulty</strong>: Hard</li><li><strong>Setup</strong>: <code>server.js</code> contains a syntax error, requires an uninstalled <code>express</code> package, AND requires a missing <code>config.json</code> containing a port number.</li><li><strong>Expected Repair</strong>: Fix syntax -&gt; <code>npm i express</code> -&gt; Create <code>config.json</code>.</li><li><strong>Verifier</strong>: Process (exit code 0).</li><li><strong>Result</strong>: <strong>FAILED</strong> (MAX_ITERATIONS - 15)</li><li><strong>Differentiation</strong>: The hardest case in the suite, intentionally designed to require a deep diagnostic loop.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The benchmark has been successfully expanded to 10 cases.</p><ul><li><strong>Overall Recovery Rate</strong>: 7/10 (70%)</li><li><strong>New Case Recovery Rate</strong>: 4/5 (80%)</li></ul><p><strong>No architectural code in <code>src/agent/</code>, <code>src/verifier/</code>, or <code>src/sandbox/</code> required modification.</strong> The system cleanly handled the new diagnostic profiles using its existing ReAct loop and deterministic verifier layers.</p>',20)])])}const p=i(a,[["render",r]]);export{h as __pageData,p as default};
